namespace DevXStream.DADS.AspNetCore;

internal static class DadsUi
{
    internal const string Html = """
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>DADS API</title><style>
:root{color-scheme:dark;--bg:#09111f;--panel:#101d30;--line:#29405e;--text:#e7effa;--muted:#9cb0c8;--brand:#37c5a5;--get:#38bdf8;--post:#a78bfa}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:15px system-ui,sans-serif}header{padding:32px max(24px,calc((100% - 1120px)/2));border-bottom:1px solid var(--line);background:linear-gradient(120deg,#102844,#09111f)}h1{margin:0;font-size:30px}header p{color:var(--muted);max-width:720px}main{max-width:1120px;margin:auto;padding:24px}.server{background:var(--panel);border:1px solid var(--line);padding:14px;border-radius:8px;margin:18px 0}section{margin:34px 0}h2{font-size:21px}.operation{border:1px solid var(--line);background:var(--panel);border-radius:8px;margin:12px 0;overflow:hidden}.summary{display:flex;gap:12px;align-items:center;padding:16px}.method{font-weight:700;padding:4px 8px;border-radius:4px;background:#173a59;color:var(--get)}.method.POST,.method.PUT,.method.PATCH{background:#302653;color:var(--post)}code{font-family:ui-monospace,monospace}.description{color:var(--muted);margin:0 16px 16px}.try{border-top:1px solid var(--line);padding:16px}.try input,.try textarea{width:100%;background:#07101c;color:var(--text);border:1px solid var(--line);border-radius:4px;padding:8px;margin:6px 0}.try textarea{min-height:90px}button{background:var(--brand);color:#06241f;border:0;border-radius:4px;padding:9px 13px;font-weight:700;cursor:pointer}pre{white-space:pre-wrap;background:#07101c;padding:12px;border-radius:4px;max-height:260px;overflow:auto}.hidden{display:none}.status{color:var(--muted)}
</style></head><body><header><h1 id="title">DADS API</h1><p id="description">Loading API definition…</p></header><main id="app"></main><script>
const app=document.getElementById('app'),esc=v=>String(v??'');
function el(n,c,t){const x=document.createElement(n);if(c)x.className=c;if(t!==undefined)x.textContent=t;return x}
function operation(module,op){const card=el('article','operation'),head=el('div','summary'),method=el('span','method '+op.method,op.method),route=el('code','',op.route);head.append(method,route);card.append(head);if(op.summary)card.append(el('p','description',op.summary));if(op.description)card.append(el('p','description',op.description));const tryBox=el('div','try'),url=el('input');url.value=(location.origin+(op.route||'')).replaceAll('{','').replaceAll('}','');const body=el('textarea','hidden');body.placeholder='JSON request body';if(op.request){body.classList.remove('hidden');body.value=op.request.example?JSON.stringify(op.request.example,null,2):''}const run=el('button','', 'Try it'),result=el('pre','status','Ready.');run.onclick=async()=>{result.textContent='Sending…';try{const init={method:op.method};if(!body.classList.contains('hidden')){init.headers={'content-type':'application/json'};init.body=body.value}const r=await fetch(url.value,init),text=await r.text();result.textContent=r.status+' '+r.statusText+'\n'+text}catch(e){result.textContent='Request failed: '+e.message}};tryBox.append(el('label','', 'Request URL'),url,body,run,result);card.append(tryBox);return card}
fetch('__DADS_DEFINITION_URL__').then(r=>r.json()).then(d=>{document.title=d.application?.name||'DADS API';document.getElementById('title').textContent=document.title;document.getElementById('description').textContent=d.application?.description||'DADS-first API documentation';if(d.servers?.length){const s=el('div','server','Server: '+d.servers[0].url);app.append(s)}for(const m of d.modules||[]){const sec=el('section'),h=el('h2','',m.name);sec.append(h);if(m.description)sec.append(el('p','description',m.description));for(const op of m.endpoints||[])sec.append(operation(m,op));app.append(sec)}}).catch(e=>app.append(el('pre','', 'Unable to load DADS definition: '+e.message)));
</script></main></body></html>
""";
}
